-- Full approved rollback reopens the original public buckets; prefer keeping privacy fixes.
BEGIN;
UPDATE storage.buckets SET public=true WHERE id IN ('creative-works','generated-audio');
UPDATE storage.buckets SET allowed_mime_types=ARRAY['image/png','image/jpeg','image/webp','image/gif'] WHERE id='creative-works';
DROP POLICY "Users can delete own creative works" ON storage.objects;
DROP POLICY IF EXISTS "Public read access for creative works" ON storage.objects;
CREATE POLICY "Public read access for creative works" ON storage.objects FOR SELECT TO "public" USING ((bucket_id = 'creative-works'::text));
DROP POLICY IF EXISTS "Users can delete own generated audio" ON storage.objects;
CREATE POLICY "Users can delete own generated audio" ON storage.objects FOR DELETE TO "public" USING (((bucket_id = 'generated-audio'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
DROP POLICY IF EXISTS "Users can read own creative works" ON storage.objects;
CREATE POLICY "Users can read own creative works" ON storage.objects FOR SELECT TO "authenticated" USING (((bucket_id = 'creative-works'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
DROP POLICY IF EXISTS "Users can read own generated audio" ON storage.objects;
CREATE POLICY "Users can read own generated audio" ON storage.objects FOR SELECT TO "public" USING (((bucket_id = 'generated-audio'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
DROP POLICY IF EXISTS "Users can update own generated audio" ON storage.objects;
CREATE POLICY "Users can update own generated audio" ON storage.objects FOR UPDATE TO "public" USING (((bucket_id = 'generated-audio'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
DROP POLICY IF EXISTS "Users can upload own generated audio" ON storage.objects;
CREATE POLICY "Users can upload own generated audio" ON storage.objects FOR INSERT TO "public" WITH CHECK (((bucket_id = 'generated-audio'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
DROP POLICY IF EXISTS "Users can upload to own folder" ON storage.objects;
CREATE POLICY "Users can upload to own folder" ON storage.objects FOR INSERT TO "authenticated" WITH CHECK (((bucket_id = 'creative-works'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
COMMIT;
